// GENERATED by scripts/sync-plugin-core.mjs from plugins/core — edit there, then re-run the sync.
// Client-agnostic session-start recall: recent memories, enriched with
// access counts and up to 3 entity names, ranked by access, plus a one-line
// hygiene nudge. Lifted verbatim from claude-code's hooks/session-start.js.
import { renderMemoryLines } from "../render.js";

const K = 10;
const KEEP = 8;
const CHAR_CAP = 6000;
// Session-start hygiene glance: run all three scans in one call. A 90-day
// staleness window keeps the "stale" nudge meaningful (genuinely cold, not
// routine 30-day-old memories that would nag every session). The health call
// overlaps the enrichment loop (concurrent, own timeout), so it adds no serial
// latency to the memory injection — and is never load-bearing.
const HEALTH_STALE_DAYS = 90;
const HEALTH_TIMEOUT_MS = 1200;

// A one-line hygiene nudge for the categories that are non-zero, or null when
// the store is tidy (or health is unavailable). Advisory — points at the tools,
// never acts.
export function renderHealth(health) {
  if (!health || !health.needs_attention) return null;
  const plur = (n, s) => `${n} ${s}${n === 1 ? "" : "s"}`;
  const parts = [];
  if (health.duplicate_pairs > 0) parts.push(plur(health.duplicate_pairs, "duplicate pair"));
  if (health.supersession_pairs > 0) parts.push(plur(health.supersession_pairs, "supersession"));
  if (health.orphan_count > 0) parts.push(plur(health.orphan_count, "orphan"));
  if (health.stale_count > 0) parts.push(`${health.stale_count} stale`);
  if (!parts.length) return null;
  return `🧹 Memory hygiene: ${parts.join(", ")} — review with memory_health, then consolidate/link/supersede.`;
}

export function renderInjection(memories, healthLine = null, charCap = CHAR_CAP) {
  if (!memories.length) return null;
  const lines = renderMemoryLines(memories, "## TopoDB memory (this project)", charCap);
  if (healthLine) lines.push(healthLine);
  lines.push("Deeper recall: search_memories / traverse. Store: remember.");
  return lines.join("\n");
}

/** The session-start recall: recent memories, enriched with access counts and
 *  up to 3 entity names, ranked by access, plus a one-line hygiene nudge.
 *  Client-agnostic: takes a connected daemon client, returns the text to
 *  inject (or null when the store is empty). Never throws for decoration
 *  failures; a recent_memories failure propagates (callers swallow). */
export async function recallForSessionStart(client, { k = K, keep = KEEP, charCap = CHAR_CAP, healthStaleDays = HEALTH_STALE_DAYS, healthTimeoutMs = HEALTH_TIMEOUT_MS } = {}) {
  const recent = await client.call("recent_memories", { k });
  const nodes = Array.isArray(recent?.memories) ? recent.memories : [];
  if (!nodes.length) return null;
  const healthPromise = client.call("memory_health", { stale_older_than_days: healthStaleDays }, healthTimeoutMs).catch(() => null);
  const enriched = [];
  for (const n of nodes) {
    if (typeof n?.id !== "string" || typeof n?.props?.content !== "string") continue;
    let accessCount = 0;
    try { const stats = await client.call("access_stats", { id: n.id }, 800); if (stats.found && typeof stats.access_count === "number") accessCount = stats.access_count; } catch { /* ranking nicety */ }
    const entities = [];
    try {
      const edges = await client.call("get_edges", { from_id: n.id }, 800);
      for (const e of (edges.edges ?? []).slice(0, 3)) {
        try { const t = await client.call("get_node", { id: e.to }, 800); const name = t?.node?.props?.name; if (typeof name === "string") entities.push(name); } catch { /* skip */ }
      }
    } catch { /* decoration */ }
    enriched.push({ id: n.id, content: n.props.content, entities, ageMs: 0, accessCount });
  }
  enriched.sort((a, b) => b.accessCount - a.accessCount);
  const healthLine = renderHealth(await healthPromise);
  return renderInjection(enriched.slice(0, keep), healthLine, charCap);
}
